<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEvaluacion, crearEvaluacion, definirGanador, guardarCondiciones, guardarPrecios, listarEvaluaciones, obtenerEvaluacion, urlCuadroComparativo } from '../services/evaluacionesEconomicas'
import type { EvaluacionEconomica, ProcesoOption, ProveedorEvaluacion } from '../interfaces/evaluacionesEconomicas.interface'
const rows=ref<EvaluacionEconomica[]>([]),states=ref<Record<string,string>>({}),processes=ref<ProcesoOption[]>([]),criterio=ref(''),state=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),createModal=ref(false),detail=ref<EvaluacionEconomica|null>(null),provider=ref<ProveedorEvaluacion|null>(null),tab=ref<'conditions'|'prices'>('conditions')
const createForm=reactive({nombre:'',proceso_id:0,observacion:''}),conditions=reactive({fecha_oferta:'',moneda_id:1,validez_oferta:'',forma_pago:'',forma_entrega:'',garantia_calidad:'',plazo_entrega:'',detalle_servicio:''}),prices=ref<Record<number,number|null>>({})
const providerTotal=computed(()=>detail.value?.items?.reduce((sum,x)=>sum+x.cantidad*(prices.value[x.detalle_id]||0),0)||0)
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarEvaluaciones(criterio.value,state.value,next);rows.value=r.data;states.value=r.estados;processes.value=r.procesos;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function openCreate(){Object.assign(createForm,{nombre:'',proceso_id:0,observacion:''});createModal.value=true}
async function saveCreate(){if(!createForm.nombre.trim()||!createForm.proceso_id){error.value='Ingrese el nombre y seleccione el proceso.';return}saving.value=true;try{await crearEvaluacion({...createForm});createModal.value=false;success.value='Evaluación económica creada correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:EvaluacionEconomica){try{detail.value=await obtenerEvaluacion(item.id);provider.value=null}catch(e){error.value=message(e)}}
function chooseProvider(item:ProveedorEvaluacion){provider.value=item;Object.assign(conditions,{fecha_oferta:item.fecha_oferta||'',moneda_id:item.moneda_id||1,validez_oferta:item.validez_oferta||'',forma_pago:item.forma_pago||'',forma_entrega:item.forma_entrega||'',garantia_calidad:item.garantia_calidad||'',plazo_entrega:item.plazo_entrega||'',detalle_servicio:item.detalle_servicio||''});prices.value={};detail.value?.items?.forEach(x=>prices.value[x.detalle_id]=x.precios[item.id]??null);tab.value='conditions'}
async function saveConditions(){if(!detail.value||!provider.value)return;if(Object.values(conditions).some(x=>x===''||x===0)){error.value='Complete todas las condiciones comerciales.';return}await action(()=>guardarCondiciones(detail.value!.id,provider.value!.id,{...conditions}),'Condiciones comerciales guardadas.')}
async function savePriceList(){if(!detail.value||!provider.value)return;const items=(detail.value.items||[]).map(x=>({detalle_id:x.detalle_id,item_id:x.item_id,pedido_id:x.pedido_id,cantidad:x.cantidad,precio:prices.value[x.detalle_id]||null}));if(!items.some(x=>(x.precio||0)>0)){error.value='Ingrese al menos un precio mayor a cero.';return}await action(()=>guardarPrecios(detail.value!.id,provider.value!.id,items),'Precios guardados correctamente.')}
async function finalize(item:EvaluacionEconomica){if(item.propuestas_count<item.proveedores_count){error.value='Todos los proveedores deben tener condiciones comerciales antes de finalizar.';return}if(!confirm('¿Finalizar la evaluación económica?'))return;await action(()=>cambiarEvaluacion(item.id,'finalizar'),'Evaluación finalizada.')}
async function cancel(item:EvaluacionEconomica){if(!confirm('¿Marcar esta evaluación como anulada?'))return;await action(()=>cambiarEvaluacion(item.id,'anular'),'Evaluación anulada.')}
async function winner(item:ProveedorEvaluacion){if(!detail.value||!confirm(`¿Seleccionar a “${item.razon_social}” como ganador?`))return;await action(()=>definirGanador(detail.value!.id,item.id),'Proveedor ganador seleccionado.');detail.value=await obtenerEvaluacion(detail.value.id)}
async function action(fn:()=>Promise<void>,text:string){saving.value=true;try{await fn();success.value=text;await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
const money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Evaluaciones económicas</nav><header class="hero"><div class="mark">EE</div><div><small>MIA · ABASTECIMIENTO</small><h1>Evaluaciones económicas</h1><p>Compara propuestas comerciales y selecciona la oferta ganadora.</p></div><b>{{total}} evaluaciones</b><button @click="openCreate">+ Nueva evaluación</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por evaluación, proceso u observación" @keyup.enter="load(1)"><select v-model="state"><option value="">Todos los estados</option><option v-for="(name,id) in states" :key="id" :value="id">{{name}}</option></select><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';state='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando evaluaciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron evaluaciones económicas.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><div class="number">#{{item.id}}</div><div><small>{{item.proceso}}</small><h2>{{item.nombre}}</h2></div><span>{{item.estado_nombre}}</span></header><p>{{item.observacion||'Sin observaciones'}}</p><div class="progress"><div><b>{{item.propuestas_count}} / {{item.proveedores_count}}</b><small>PROPUESTAS COMPLETAS</small></div><progress :value="item.propuestas_count" :max="item.proveedores_count||1"></progress></div><dl><div><dt>Evaluador</dt><dd>{{item.usuario_evalua}}</dd></div><div><dt>Fecha</dt><dd>{{item.fecha}}</dd></div></dl><footer><button @click="show(item)">Gestionar ofertas</button><a :href="urlCuadroComparativo(item.id)" target="_blank">Cuadro comparativo</a><button v-if="item.estado===1" @click="finalize(item)">Finalizar</button><button class="danger" @click="cancel(item)">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="createModal" class="backdrop" @mousedown.self="createModal=false"><form class="dialog small-dialog" @submit.prevent="saveCreate"><header><div><small>NUEVA EVALUACIÓN</small><h2>Registrar evaluación económica</h2></div><button type="button" @click="createModal=false">×</button></header><label>Nombre *<input v-model.trim="createForm.nombre"></label><label>Proceso *<select v-model.number="createForm.proceso_id"><option :value="0">Seleccione</option><option v-for="x in processes" :key="x.id" :value="x.id">{{x.nombre}} · {{x.proveedores_count}} proveedores</option></select></label><label>Observación<textarea v-model.trim="createForm.observacion" rows="3"></textarea></label><footer><button type="button" class="soft" @click="createModal=false">Cancelar</button><button :disabled="saving">Crear evaluación</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog manager"><header><div><small>PROCESO {{detail.proceso}}</small><h2>{{detail.nombre}}</h2></div><button @click="detail=null">×</button></header><div class="provider-list"><button v-for="x in detail.proveedores||[]" :key="x.id" :class="{selected:provider?.id===x.id,winner:detail.ganador_id===x.id}" @click="chooseProvider(x)"><b>{{x.razon_social}}</b><span>RUC {{x.ruc}}</span><em>{{x.condiciones_guardadas?'Completo':'Pendiente'}}</em></button></div><div v-if="provider" class="workspace"><nav class="tabs"><button :class="{active:tab==='conditions'}" @click="tab='conditions'">Condiciones comerciales</button><button :class="{active:tab==='prices'}" @click="tab='prices'">Precios por ítem</button></nav><div v-if="tab==='conditions'" class="grid"><label>Fecha de oferta<input v-model="conditions.fecha_oferta" type="date"></label><label>Moneda<select v-model.number="conditions.moneda_id"><option :value="1">Soles</option><option :value="2">Dólares</option></select></label><label>Validez de oferta<input v-model.trim="conditions.validez_oferta"></label><label>Forma de pago<input v-model.trim="conditions.forma_pago"></label><label>Forma de entrega<input v-model.trim="conditions.forma_entrega"></label><label>Garantía de calidad<input v-model.trim="conditions.garantia_calidad"></label><label>Plazo de entrega<input v-model.trim="conditions.plazo_entrega"></label><label>Detalle del servicio<input v-model.trim="conditions.detalle_servicio"></label><footer><button :disabled="saving" @click="saveConditions">Guardar condiciones</button></footer></div><div v-else class="price-table"><table><thead><tr><th>Pedido</th><th>Ítem</th><th>Unidad</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th></tr></thead><tbody><tr v-for="x in detail.items||[]" :key="x.detalle_id"><td>#{{x.pedido_id}}</td><td>{{x.nombre}}</td><td>{{x.unidad}}</td><td>{{x.cantidad}}</td><td><input v-model.number="prices[x.detalle_id]" type="number" min="0" step="0.01"></td><td>{{money(x.cantidad*(prices[x.detalle_id]||0))}}</td></tr></tbody></table><footer><b>Total ofertado: {{money(providerTotal)}}</b><button @click="savePriceList">Guardar precios</button></footer></div><button v-if="detail.estado>=2" class="winner-btn" @click="winner(provider)">Seleccionar como ganador</button></div><div v-else class="select-provider">Seleccione un proveedor para registrar sus condiciones y precios.</div></section></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>b{margin-left:auto;font-size:.55rem}.hero button,.filters button,.pages button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:11px;padding:11px;display:grid;grid-template-columns:1fr .5fr auto auto;gap:6px;border-radius:9px;background:#fff}.soft{color:#64727a!important;background:#edf1f3!important}input,select,textarea{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.55rem}.empty{margin-top:11px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #8a5ca2;border-radius:9px;background:#fff}.cards article>header{display:flex;align-items:center;gap:8px}.number{padding:8px;border-radius:8px;color:#fff;background:#8a5ca2;font-size:.55rem}.cards h2{margin:2px 0;font-size:.68rem}.cards header span{margin-left:auto;padding:4px 6px;border-radius:8px;color:#6b477e;background:#f1e9f5;font-size:.43rem}.cards>article>p{min-height:28px;color:#748188;font-size:.5rem}.progress{padding:8px;border-radius:7px;background:#f5f7f8}.progress div{display:flex}.progress small{margin-left:auto}.progress progress{width:100%;height:5px}.cards dl div{padding:4px 0;display:flex;font-size:.49rem}.cards dd{margin-left:auto}.cards footer{display:flex;gap:4px;flex-wrap:wrap}.cards footer button,.cards footer a{border:0;color:#765087;background:none;text-decoration:none;font-size:.47rem}.cards footer .danger{margin-left:auto;color:#b53f46}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(1100px,100%);max-height:92vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.small-dialog{width:min(600px,100%)}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.small-dialog label{display:block;margin-bottom:8px;font-size:.51rem}.dialog>footer,.grid>footer{margin-top:10px;display:flex;justify-content:flex-end;gap:6px}.provider-list{display:flex;gap:5px;overflow:auto}.provider-list button{min-width:180px;display:grid;text-align:left;color:#4e5c63;background:#f5f7f8;border:2px solid transparent}.provider-list button.selected{border-color:var(--accent)}.provider-list button.winner{background:#e7f7ef}.provider-list span,.provider-list em{font-size:.45rem}.provider-list em{color:#287154;font-style:normal}.workspace{margin-top:12px}.tabs{display:flex;border-bottom:1px solid #e0e5e7}.tabs button{color:#68767d;background:none;border-radius:0}.tabs .active{color:var(--accent);border-bottom:2px solid var(--accent)}.grid{margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.grid label{font-size:.5rem}.grid footer{grid-column:1/-1}.price-table{margin-top:10px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:.5rem}th,td{padding:8px;border-bottom:1px solid #e7ebed;text-align:left}th{color:#fff;background:#5b6e8e}.price-table input{min-width:90px}.price-table footer{padding:10px;display:flex;align-items:center;justify-content:flex-end;gap:10px}.winner-btn{float:right;background:#2d9b68!important}.select-provider{padding:45px;text-align:center;font-size:.56rem}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards,.grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr 1fr}}
</style>
